-- Explicações por artigo — Lei de Execução Penal (Lei nº 7.210, de 1984). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A execução penal tem por objetivo efetivar as disposições de sentença ou decisão criminal e proporcionar condições para a harmônica integração social do condenado e do internado.', '["Efetivar a sentença ou decisão criminal.","Proporcionar a harmônica integração social do condenado e do internado."]'::jsonb, '["Dupla finalidade: punitiva (cumprir a sentença) e ressocializadora (integração social)."]'::jsonb, 'A execução da pena busca cumprir a sentença e preparar o condenado para voltar à sociedade.', '["Assertiva que atribui à execução penal apenas a finalidade de punir erra: ela também busca a integração social."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A jurisdição penal dos juízes ou tribunais da justiça ordinária, em todo o território nacional, será exercida, no processo de execução, na conformidade da Lei de Execução Penal e do Código de Processo Penal. A Lei aplica-se igualmente ao preso provisório e ao condenado pela Justiça Eleitoral ou Militar, quando recolhido a estabelecimento sujeito à jurisdição ordinária.', '["Jurisdição da justiça ordinária.","Aplica-se ao preso provisório.","Aplica-se ao condenado pela Justiça Eleitoral ou Militar recolhido em estabelecimento comum."]'::jsonb, '["A LEP também alcança o PRESO PROVISÓRIO."]'::jsonb, 'O preso provisório tem os direitos da LEP, no que couber.', '["Assertiva que afasta a LEP do preso provisório erra: ela se aplica igualmente."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao condenado e ao internado serão assegurados todos os direitos não atingidos pela sentença ou pela lei. Não haverá qualquer distinção de natureza racial, social, religiosa ou política.', '["Todos os direitos não atingidos pela sentença ou pela lei.","Vedada a distinção racial, social, religiosa ou política."]'::jsonb, '["O condenado só perde os direitos restringidos pela sentença ou pela lei."]'::jsonb, 'O preso mantém o direito à integridade física, que a pena não retira.', '["Assertiva que retira do condenado todos os direitos fundamentais erra: só os atingidos pela sentença ou pela lei."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

