insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os condenados serão classificados, segundo os seus antecedentes e personalidade, para orientar a individualização da execução penal.', '["Classificação conforme antecedentes e personalidade.","Individualização da execução."]'::jsonb, '["Individualização da pena na fase de execução."]'::jsonb, 'O condenado é classificado para receber o programa mais adequado.', '["Assertiva que dispensa a classificação dos condenados erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
