insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A classificação será feita por Comissão Técnica de Classificação, que elaborará o programa individualizador da pena privativa de liberdade adequada ao condenado ou preso provisório.', '["Comissão Técnica de Classificação.","Programa individualizador da pena."]'::jsonb, '["Alcança também o preso provisório."]'::jsonb, 'A Comissão elabora o programa individualizador de um preso recém-chegado.', '["Assertiva que atribui a classificação ao juiz da execução erra: é da Comissão Técnica."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
