insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado à pena de reclusão em regime inicial fechado será submetido obrigatoriamente à identificação do perfil genético, mediante extração de DNA, por técnica adequada e indolor, por ocasião do ingresso no estabelecimento prisional. O perfil será armazenado em banco de dados sigiloso, com garantias de proteção de dados genéticos. A autoridade policial poderá requerer ao juiz, em inquérito instaurado, o acesso ao banco. O titular tem acesso aos seus dados e à cadeia de custódia. Quem não foi submetido à coleta no ingresso deverá sê-lo durante a pena. A amostra só pode servir à identificação pelo perfil genético, vedada a fenotipagem genética, e é descartada após a identificação, guardando-se material para nova perícia. A coleta é feita por agente treinado, e o laudo por perito oficial. Nos crimes hediondos e equiparados, os vestígios devem ser processados, se possível, em até 30 dias.', '["Coleta obrigatória de DNA do condenado à reclusão em regime inicial fechado.","Banco de dados sigiloso.","Vedada a fenotipagem genética.","Laudo por perito oficial.","Hediondos: processamento em até 30 dias."]'::jsonb, '["ATUALIZAÇÃO: redação dada pelo Pacote Anticrime.","Recusar a coleta é FALTA GRAVE (art. 50, VIII)."]'::jsonb, 'Ao ingressar no presídio, o condenado em regime inicial fechado tem o DNA coletado.', '["Assertiva que autoriza a fenotipagem genética com a amostra coletada erra: é vedada."]'::jsonb, '[]'::jsonb, '["Art. 50, VIII"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-9-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

