select u.id, u.content_sha256, 'Incumbe ao serviço de assistência social conhecer os resultados dos diagnósticos ou exames; relatar por escrito ao diretor os problemas do assistido; acompanhar o resultado das permissões de saídas e saídas temporárias; promover a recreação; orientar o assistido na fase final da pena e o liberando; providenciar documentos, benefícios previdenciários e seguro por acidente no trabalho; e orientar e amparar a família do preso, do internado e da vítima.', '["Acompanhar saídas temporárias.","Promover recreação.","Orientar na fase final da pena.","Providenciar documentos e benefícios.","Amparar a família do preso e da vítima."]'::jsonb, '["Também ampara a família da VÍTIMA."]'::jsonb, 'O assistente social providencia os documentos do preso que está para ser solto.', '["Assertiva que exclui o amparo à família da vítima erra."]'::jsonb, '[]'::jsonb, '["Art. 22"]'::jsonb, 'under_review', 'claude'
