select u.id, u.content_sha256, 'A assistência religiosa, com liberdade de culto, será prestada aos presos e aos internados, permitindo-se-lhes a participação nos serviços organizados no estabelecimento e a posse de livros de instrução religiosa. No estabelecimento haverá local apropriado para os cultos. Nenhum preso ou internado poderá ser obrigado a participar de atividade religiosa.', '["Liberdade de culto.","Local apropriado para cultos.","Vedada a obrigatoriedade."]'::jsonb, '["Nenhum preso é OBRIGADO a participar."]'::jsonb, 'O preso participa do culto de sua religião, por vontade própria.', '["Assertiva que obriga o preso a participar de atividade religiosa erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
