select u.id, u.content_sha256, 'As tarefas executadas como prestação de serviço à comunidade não serão remuneradas.', '["Prestação de serviço à comunidade não é remunerada."]'::jsonb, '["Gratuita por natureza."]'::jsonb, 'O condenado que presta serviços à comunidade não recebe salário.', '["Assertiva que prevê remuneração para a prestação de serviço à comunidade erra."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
