insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado à pena privativa de liberdade está obrigado ao trabalho na medida de suas aptidões e capacidade. Para o preso provisório, o trabalho não é obrigatório e só poderá ser executado no interior do estabelecimento.', '["Trabalho obrigatório para o condenado.","Preso provisório: facultativo e só interno."]'::jsonb, '["Preso PROVISÓRIO: trabalho facultativo e apenas interno."]'::jsonb, 'O preso provisório pode optar por trabalhar dentro da unidade.', '["Assertiva que obriga o preso provisório a trabalhar erra."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-31'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na atribuição do trabalho deverão ser levadas em conta a habilitação, a condição pessoal e as necessidades futuras do preso, bem como as oportunidades do mercado. Deverá ser limitado o artesanato sem expressão econômica, salvo nas regiões de turismo. Os maiores de sessenta anos poderão solicitar ocupação adequada à sua idade, e os doentes ou deficientes físicos somente exercerão atividades apropriadas ao seu estado.', '["Habilitação, condição pessoal e mercado.","Artesanato sem expressão econômica é limitado.","Maiores de 60 anos: ocupação adequada.","Doentes e deficientes: atividades apropriadas."]'::jsonb, '["Maiores de sessenta anos podem SOLICITAR ocupação adequada."]'::jsonb, 'O preso idoso solicita uma função leve.', '["Assertiva que obriga a mesma atividade a todos os presos erra."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-32'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A jornada normal de trabalho não será inferior a seis, nem superior a oito horas, com descanso nos domingos e feriados. Poderá ser atribuído horário especial aos presos designados para os serviços de conservação e manutenção do estabelecimento penal.', '["Jornada de seis a oito horas.","Descanso nos domingos e feriados.","Horário especial para serviços de manutenção."]'::jsonb, '["Mínimo de seis e máximo de oito horas."]'::jsonb, 'A jornada do preso é de, no mínimo, seis e, no máximo, oito horas.', '["Assertiva que fixa a jornada máxima em dez horas erra: são oito."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-33'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O trabalho poderá ser gerenciado por fundação, ou empresa pública, com autonomia administrativa, e terá por objetivo a formação profissional do condenado. Nessa hipótese, incumbirá à entidade gerenciadora promover e supervisionar a produção, com critérios e métodos empresariais, encarregar-se de sua comercialização, bem como suportar despesas, inclusive o pagamento de remuneração adequada.', '["Gerenciamento por fundação ou empresa pública.","Objetivo: formação profissional.","A entidade promove, supervisiona, comercializa e paga a remuneração."]'::jsonb, '["Gestão por fundação ou empresa PÚBLICA."]'::jsonb, 'Uma fundação gerencia a oficina de marcenaria da unidade.', '["Assertiva que atribui a gestão do trabalho prisional a empresa privada exclusivamente erra."]'::jsonb, '[]'::jsonb, '["Art. 35"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-34'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos da administração direta ou indireta da União, Estados, Territórios, Distrito Federal e Municípios adquirirão, com dispensa de concorrência pública, os bens ou produtos do trabalho prisional, sempre que não for possível ou recomendável a venda a particulares. As importâncias arrecadadas revertem em favor da fundação ou empresa pública gerenciadora ou, na falta, do estabelecimento penal.', '["Compra pública sem licitação dos produtos do trabalho prisional.","Receitas revertem à fundação ou ao estabelecimento."]'::jsonb, '["Dispensa de CONCORRÊNCIA PÚBLICA."]'::jsonb, 'A prefeitura compra as carteiras escolares produzidas pelos presos sem licitação.', '["Assertiva que exige licitação para a compra dos produtos do trabalho prisional erra: há dispensa."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-35'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O trabalho externo será admissível para os presos em regime fechado somente em serviço ou obras públicas realizados por órgãos da administração direta ou indireta, ou entidades privadas, desde que tomadas as cautelas contra a fuga e em favor da disciplina. O limite máximo do número de presos será de dez por cento do total de empregados na obra. A remuneração cabe ao órgão, à entidade ou à empresa empreiteira. A prestação de trabalho a entidade privada depende do consentimento expresso do preso.', '["Trabalho externo no regime fechado: serviço ou obra pública.","Limite de dez por cento dos empregados.","Remuneração pela contratante.","Entidade privada: consentimento expresso do preso."]'::jsonb, '["Teto de 10% do total de empregados da obra."]'::jsonb, 'Em uma obra pública com cem empregados, no máximo dez presos do regime fechado trabalham.', '["Assertiva que dispensa o consentimento do preso para trabalhar em entidade privada erra."]'::jsonb, '[]'::jsonb, '["Art. 37"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-36'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prestação de trabalho externo, a ser autorizada pela direção do estabelecimento, dependerá de aptidão, disciplina e responsabilidade, além do cumprimento mínimo de um sexto da pena. Revogar-se-á a autorização ao preso que praticar crime, for punido por falta grave ou tiver comportamento contrário aos requisitos.', '["Autorização da direção.","Aptidão, disciplina e responsabilidade.","Cumprimento mínimo de um sexto da pena.","Revogação por crime ou falta grave."]'::jsonb, '["Mínimo de UM SEXTO da pena."]'::jsonb, 'O preso só obtém o trabalho externo após cumprir um sexto da pena.', '["Assertiva que fixa em dois quintos o mínimo de pena para o trabalho externo erra: é um sexto."]'::jsonb, '[]'::jsonb, '["Art. 36"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-37'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cumpre ao condenado, além das obrigações legais inerentes ao seu estado, submeter-se às normas de execução da pena.', '["Submissão às normas de execução."]'::jsonb, '["Dever de obediência às normas."]'::jsonb, 'O condenado deve seguir as regras da unidade.', '["Assertiva que isenta o condenado das normas de execução erra."]'::jsonb, '[]'::jsonb, '["Art. 39"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-38'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constituem deveres do condenado: comportamento disciplinado e cumprimento fiel da sentença; obediência ao servidor e respeito a qualquer pessoa; urbanidade com os demais condenados; conduta oposta a movimentos de fuga ou subversão; execução do trabalho, tarefas e ordens recebidas; submissão à sanção disciplinar; indenização à vítima ou sucessores; indenização ao Estado das despesas com sua manutenção, mediante desconto proporcional da remuneração; higiene pessoal e asseio da cela; e conservação dos objetos de uso pessoal. Aplica-se ao preso provisório, no que couber.', '["Disciplina e cumprimento da sentença.","Respeito e urbanidade.","Trabalho e submissão à sanção.","Indenização à vítima e ao Estado.","Higiene e conservação de objetos."]'::jsonb, '["Os incisos II e V são ligados à falta grave (art. 50, VI)."]'::jsonb, 'O condenado deve manter a cela limpa e respeitar os agentes.', '["Assertiva que isenta o preso provisório de todos os deveres do art. 39 erra: aplicam-se, no que couber."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-39'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Impõe-se a todas as autoridades o respeito à integridade física e moral dos condenados e dos presos provisórios.', '["Respeito à integridade física e moral."]'::jsonb, '["Alcança condenados e presos provisórios."]'::jsonb, 'Nenhum agente pode agredir o preso.', '["Assertiva que limita o respeito à integridade aos condenados erra: abrange os presos provisórios."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-40'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constituem direitos do preso: alimentação suficiente e vestuário; trabalho e remuneração; previdência social; pecúlio; proporcionalidade na distribuição do tempo para trabalho, descanso e recreação; exercício das atividades anteriores compatíveis; assistência material, à saúde, jurídica, educacional, social e religiosa; proteção contra o sensacionalismo; entrevista pessoal e reservada com o advogado; visita do cônjuge, companheira, parentes e amigos em dias determinados; chamamento nominal; igualdade de tratamento; audiência com o diretor; representação e petição a qualquer autoridade; contato com o mundo exterior por correspondência e leitura; e atestado de pena a cumprir, emitido anualmente. Os direitos dos incisos V, X e XV podem ser suspensos ou restringidos por ato motivado do juiz da execução. O preso condenado por crime contra a mulher por razões da condição do sexo feminino não poderá usufruir da visita íntima ou conjugal.', '["Rol de direitos do preso.","Entrevista pessoal e reservada com o advogado.","Atestado de pena a cumprir anual.","Suspensão de direitos dos incisos V, X e XV por ato motivado do juiz.","Sem visita íntima para condenado por crime contra a mulher por razões do sexo feminino."]'::jsonb, '["ATUALIZAÇÃO: o §2º (sem visita íntima, em crime contra a mulher) foi incluído por lei posterior.","Só o JUIZ pode suspender os direitos dos incisos V, X e XV."]'::jsonb, 'O preso recebe o atestado de pena a cumprir uma vez por ano.', '["Assertiva que permite ao diretor suspender a visita por ato próprio erra: depende de ato motivado do juiz da execução."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-41'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os encontros no parlatório ou por meio virtual entre presos provisórios ou condenados vinculados a organizações criminosas ultraviolentas, grupos paramilitares ou milícias privadas e seus visitantes poderão ser monitorados por captação audiovisual e gravação. O monitoramento poderá ser requerido pelo delegado, pelo Ministério Público ou pela administração penitenciária. A visitação e o monitoramento nos estabelecimentos federais de segurança máxima sujeitam-se às regras especiais da Lei nº 11.671, de 8 de maio de 2008.', '["Monitoramento audiovisual dos encontros de presos de facções.","Requerimento do delegado, MP ou administração penitenciária.","Regras especiais nos presídios federais."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído pela Lei Antifacção."]'::jsonb, 'A visita ao líder de uma facção pode ser gravada.', '["Assertiva que veda o monitoramento das visitas a presos de facções erra."]'::jsonb, '[]'::jsonb, '["Lei Antifacção"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-41-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O conteúdo das comunicações monitoradas entre advogado e cliente, quando o monitoramento houver sido autorizado por razões fundadas de conluio criminoso reconhecidas judicialmente, será submetido à análise exclusiva do juízo competente para o controle da legalidade da investigação, distinto do juízo da instrução e do julgamento. O juízo de controle decide sobre a licitude, a pertinência e a necessidade da prova e sua eventual inutilização, antes de qualquer remessa ao juízo da instrução. As gravações que não interessarem à prova serão inutilizadas. O conteúdo das comunicações indeferidas ou declaradas ilícitas não pode ser acessado pelo juízo da instrução.', '["Análise por juízo de controle distinto do da instrução.","Decisão sobre licitude, pertinência e necessidade.","Inutilização do que não interessa à prova.","Vedado o acesso do juízo da instrução ao conteúdo ilícito."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído pela Lei Antifacção.","Juízo de controle DISTINTO do juízo da instrução."]'::jsonb, 'Um juiz diferente do que vai julgar o caso analisa as conversas entre advogado e cliente monitoradas.', '["Assertiva que permite ao juiz da instrução acessar as comunicações declaradas ilícitas erra."]'::jsonb, '[]'::jsonb, '["Art. 41-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-41-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplica-se ao preso provisório e ao submetido à medida de segurança, no que couber, o disposto nesta Seção.', '["Direitos e deveres também ao preso provisório e ao submetido a medida de segurança."]'::jsonb, '["Extensão ''no que couber''."]'::jsonb, 'O preso provisório tem os mesmos direitos de visita do condenado.', '["Assertiva que exclui o submetido a medida de segurança da Seção erra."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-42'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É garantida a liberdade de contratar médico de confiança pessoal do internado ou do submetido a tratamento ambulatorial, por seus familiares ou dependentes, a fim de orientar e acompanhar o tratamento. As divergências entre o médico oficial e o particular serão resolvidas pelo juiz de execução.', '["Médico de confiança pessoal.","Divergências resolvidas pelo juiz da execução."]'::jsonb, '["Quem decide a divergência é o JUIZ DA EXECUÇÃO."]'::jsonb, 'A família contrata um médico particular para acompanhar o internado.', '["Assertiva que atribui ao diretor a solução das divergências entre médicos erra: é do juiz da execução."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-43'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A disciplina consiste na colaboração com a ordem, na obediência às determinações das autoridades e seus agentes e no desempenho do trabalho. Estão sujeitos à disciplina o condenado à pena privativa de liberdade ou restritiva de direitos e o preso provisório.', '["Colaboração com a ordem, obediência e trabalho.","Sujeitos: condenados e preso provisório."]'::jsonb, '["Alcança também as penas restritivas de direitos."]'::jsonb, 'O condenado a pena restritiva também se sujeita à disciplina.', '["Assertiva que isenta o preso provisório da disciplina erra."]'::jsonb, '[]'::jsonb, '["Art. 45"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-44'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não haverá falta nem sanção disciplinar sem expressa e anterior previsão legal ou regulamentar. As sanções não poderão colocar em perigo a integridade física e moral do condenado. É vedado o emprego de cela escura. São vedadas as sanções coletivas.', '["Legalidade das faltas e sanções.","Vedadas sanções que ameacem a integridade.","Vedada a cela escura.","Vedadas as sanções coletivas."]'::jsonb, '["Vedadas: CELA ESCURA e SANÇÕES COLETIVAS."]'::jsonb, 'A unidade não pode punir todos os presos de uma ala pela falta de um só.', '["Assertiva que admite sanção coletiva erra: é vedada."]'::jsonb, '[]'::jsonb, '["Art. 53"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-45'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado ou denunciado, no início da execução da pena ou da prisão, será cientificado das normas disciplinares.', '["Ciência das normas disciplinares no início da execução."]'::jsonb, '["Dever de informação."]'::jsonb, 'O preso recebe as regras disciplinares ao ingressar.', '["Assertiva que dispensa a ciência das normas disciplinares erra."]'::jsonb, '[]'::jsonb, '["Art. 45"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-46'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder disciplinar, na execução da pena privativa de liberdade, será exercido pela autoridade administrativa conforme as disposições regulamentares.', '["Poder disciplinar exercido pela autoridade administrativa."]'::jsonb, '["Autoridade ADMINISTRATIVA."]'::jsonb, 'O diretor aplica a sanção disciplinar prevista no regulamento.', '["Assertiva que atribui ao juiz o poder disciplinar na pena privativa erra: é da autoridade administrativa."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-47'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na execução das penas restritivas de direitos, o poder disciplinar será exercido pela autoridade administrativa a que estiver sujeito o condenado. Nas faltas graves, a autoridade representará ao juiz da execução para os fins dos artigos 118, inciso I, 125, 127, 181, §§ 1º, letra d, e 2º da Lei.', '["Poder disciplinar pela autoridade administrativa.","Faltas graves: representação ao juiz."]'::jsonb, '["Nas faltas graves, quem decide as consequências é o JUIZ."]'::jsonb, 'A falta grave do condenado a pena restritiva é comunicada ao juiz.', '["Assertiva que permite à autoridade administrativa converter a pena sozinha erra."]'::jsonb, '[]'::jsonb, '["Art. 118"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-48'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As faltas disciplinares classificam-se em leves, médias e graves. A legislação local especificará as leves e médias, bem assim as respectivas sanções. Pune-se a tentativa com a sanção correspondente à falta consumada.', '["Faltas leves, médias e graves.","Leves e médias: legislação local.","Tentativa punida como falta consumada."]'::jsonb, '["As faltas GRAVES estão na lei federal; leves e médias, na legislação local."]'::jsonb, 'A tentativa de fuga é punida como a fuga.', '["Assertiva que não pune a tentativa de falta disciplinar erra: pune-se como a falta consumada."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-49'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete falta grave o condenado à pena privativa de liberdade que incitar ou participar de movimento para subverter a ordem ou a disciplina; fugir; possuir indevidamente instrumento capaz de ofender a integridade física de outrem; provocar acidente de trabalho; descumprir, no regime aberto, as condições impostas; inobservar os deveres dos incisos II e V do art. 39; ter em sua posse, utilizar ou fornecer aparelho telefônico, de rádio ou similar; recusar-se ao procedimento de identificação do perfil genético; ou aproximar-se da residência ou do local de trabalho da vítima ou de seus familiares, em violação a medidas protetivas, nos casos de violência doméstica. Aplica-se, no que couber, ao preso provisório.', '["Nove hipóteses de falta grave.","Fuga, subversão, posse de celular.","Recusa na coleta de DNA.","Aproximação da vítima de violência doméstica."]'::jsonb, '["ATUALIZAÇÃO: incisos VII a IX incluídos por leis posteriores (celular, DNA e aproximação da vítima).","Posse de CELULAR é falta grave."]'::jsonb, 'O preso que é flagrado com um celular comete falta grave.', '["Assertiva que considera falta leve a posse de aparelho celular erra: é falta grave."]'::jsonb, '[]'::jsonb, '["Art. 52"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-50'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete falta grave o condenado à pena restritiva de direitos que descumprir, injustificadamente, a restrição imposta; retardar, injustificadamente, o cumprimento da obrigação imposta; ou inobservar os deveres previstos nos incisos II e V do art. 39.', '["Descumprir a restrição.","Retardar a obrigação.","Inobservar deveres dos incisos II e V do art. 39."]'::jsonb, '["Falta grave específica das penas restritivas."]'::jsonb, 'Quem não comparece ao serviço comunitário sem justificativa comete falta grave.', '["Assertiva que exige conduta violenta para a falta grave do art. 51 erra."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-51'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prática de fato previsto como crime doloso constitui falta grave e, quando ocasionar subversão da ordem ou disciplina internas, sujeitará o preso provisório ou condenado, nacional ou estrangeiro, sem prejuízo da sanção penal, ao regime disciplinar diferenciado (RDD), com duração máxima de até 2 anos, recolhimento em cela individual, visitas quinzenais de 2 pessoas por vez e duração de 2 horas, saída da cela por 2 horas diárias para banho de sol em grupos de até 4 presos sem contato com o mesmo grupo criminoso, entrevistas monitoradas, fiscalização da correspondência e participação em audiências preferencialmente por videoconferência. Também se aplica ao preso que apresente alto risco ou sobre o qual recaiam fundadas suspeitas de participação em organização criminosa, associação criminosa ou milícia. Havendo liderança em organização criminosa ou atuação em 2 ou mais Estados, o RDD será obrigatoriamente cumprido em presídio federal. Pode ser prorrogado sucessivamente por períodos de 1 ano. As visitas são gravadas, e após 6 meses sem visita o preso pode ter contato telefônico gravado duas vezes por mês por 10 minutos. Aplica-se ao autor de violência doméstica que ameace a vítima.', '["RDD: duração máxima de até 2 anos, prorrogável por períodos de 1 ano.","Cela individual e visitas quinzenais.","Banho de sol de 2 horas em grupos de até 4 presos.","Alto risco ou suspeita de integrar organização criminosa.","Presídio federal se líder ou atuação em 2 ou mais Estados.","Aplicável ao autor de violência doméstica que ameace a vítima."]'::jsonb, '["ATUALIZAÇÃO: redação dada pelo Pacote Anticrime e ampliada por leis posteriores.","RDD: até 2 ANOS, prorrogável por períodos de 1 ano."]'::jsonb, 'O líder de facção que comanda ações de dentro do presídio é colocado no RDD em unidade federal.', '["Assertiva que fixa em um ano a duração máxima inicial do RDD erra: é de até 2 anos."]'::jsonb, '[{"termo":"RDD","significado":"Regime disciplinar diferenciado."}]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-52'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constituem sanções disciplinares a advertência verbal; a repreensão; a suspensão ou restrição de direitos; o isolamento na própria cela ou em local adequado, nos estabelecimentos com alojamento coletivo; e a inclusão no regime disciplinar diferenciado.', '["Advertência verbal.","Repreensão.","Suspensão ou restrição de direitos.","Isolamento.","Regime disciplinar diferenciado."]'::jsonb, '["Cinco sanções disciplinares."]'::jsonb, 'O preso recebe advertência verbal por falta leve.', '["Assertiva que inclui a cela escura entre as sanções erra: é vedada."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-53'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As sanções dos incisos I a IV do art. 53 serão aplicadas por ato motivado do diretor do estabelecimento, e a do inciso V (regime disciplinar diferenciado), por prévio e fundamentado despacho do juiz competente. A inclusão no RDD depende de requerimento circunstanciado do diretor ou outra autoridade administrativa. O juiz decidirá liminarmente e prolatará decisão final no prazo máximo de 15 dias, após manifestação do Ministério Público e da defesa. A ausência de manifestação não impede a decisão.', '["Diretor aplica as sanções dos incisos I a IV.","Juiz decide o RDD.","Decisão final em até 15 dias."]'::jsonb, '["RDD só por decisão do JUIZ, em até 15 dias."]'::jsonb, 'O diretor aplica a repreensão, mas só o juiz inclui o preso no RDD.', '["Assertiva que permite ao diretor incluir o preso no RDD erra: exige despacho do juiz."]'::jsonb, '[]'::jsonb, '["Art. 52"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-54'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As recompensas têm em vista o bom comportamento reconhecido em favor do condenado, de sua colaboração com a disciplina e de sua dedicação ao trabalho.', '["Recompensas por bom comportamento, colaboração e trabalho."]'::jsonb, '["Reconhecem o mérito do condenado."]'::jsonb, 'O preso que trabalha com dedicação recebe elogio.', '["Assertiva que prevê recompensa apenas para quem tem bom comportamento sem considerar o trabalho erra."]'::jsonb, '[]'::jsonb, '["Art. 56"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-55'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São recompensas o elogio e a concessão de regalias. A legislação local e os regulamentos estabelecerão a natureza e a forma de concessão de regalias.', '["Elogio.","Concessão de regalias."]'::jsonb, '["Regalias definidas pela legislação local."]'::jsonb, 'O preso recebe elogio por seu bom comportamento.', '["Assertiva que prevê a redução automática da pena como recompensa do art. 56 erra."]'::jsonb, '[]'::jsonb, '["Art. 55"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-56'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na aplicação das sanções disciplinares, levar-se-ão em conta a natureza, os motivos, as circunstâncias e as consequências do fato, bem como a pessoa do faltoso e seu tempo de prisão. Nas faltas graves, aplicam-se as sanções dos incisos III a V do art. 53.', '["Critérios de aplicação das sanções.","Faltas graves: suspensão, isolamento ou RDD."]'::jsonb, '["Faltas graves levam às sanções dos incisos III a V."]'::jsonb, 'A sanção considera o motivo, as circunstâncias e o tempo de prisão do faltoso.', '["Assertiva que permite a advertência verbal como sanção da falta grave erra."]'::jsonb, '[]'::jsonb, '["Art. 53"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-57'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O isolamento, a suspensão e a restrição de direitos não poderão exceder a trinta dias, ressalvada a hipótese do regime disciplinar diferenciado. O isolamento será sempre comunicado ao juiz da execução.', '["Limite de trinta dias.","Exceção: RDD.","Comunicação do isolamento ao juiz."]'::jsonb, '["Limite de TRINTA dias, exceto no RDD."]'::jsonb, 'O isolamento por falta disciplinar não passa de trinta dias.', '["Assertiva que fixa em sessenta dias o limite do isolamento erra: são trinta."]'::jsonb, '[]'::jsonb, '["Art. 52"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-58'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Praticada a falta disciplinar, deverá ser instaurado o procedimento para sua apuração, conforme regulamento, assegurado o direito de defesa. A decisão será motivada.', '["Procedimento de apuração.","Direito de defesa.","Decisão motivada."]'::jsonb, '["Defesa e motivação são obrigatórias."]'::jsonb, 'O preso se defende antes de ser punido.', '["Assertiva que dispensa a defesa na apuração da falta disciplinar erra."]'::jsonb, '[]'::jsonb, '["Art. 60"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-59'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade administrativa poderá decretar o isolamento preventivo do faltoso pelo prazo de até dez dias. A inclusão do preso no regime disciplinar diferenciado, no interesse da disciplina e da averiguação do fato, dependerá de despacho do juiz competente. O tempo de isolamento ou inclusão preventiva no RDD será computado no período de cumprimento da sanção disciplinar.', '["Isolamento preventivo de até dez dias.","RDD preventivo depende do juiz.","Detração do tempo de isolamento preventivo."]'::jsonb, '["Isolamento preventivo: até DEZ dias."]'::jsonb, 'O diretor isola preventivamente o preso por até dez dias.', '["Assertiva que fixa em trinta dias o isolamento preventivo erra: são dez."]'::jsonb, '[]'::jsonb, '["Art. 58"]'::jsonb, 'under_review', 'claude'
