insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao Conselho Nacional de Política Criminal e Penitenciária incumbe propor diretrizes da política criminal; contribuir na elaboração de planos nacionais de desenvolvimento; promover a avaliação periódica do sistema criminal; estimular a pesquisa criminológica; elaborar programa nacional de formação do servidor; estabelecer regras sobre a arquitetura de estabelecimentos penais; estabelecer critérios para a estatística criminal; inspecionar e fiscalizar os estabelecimentos penais; representar ao juiz ou à autoridade administrativa para instauração de sindicância; e representar à autoridade competente para a interdição de estabelecimento penal.', '["Diretrizes de política criminal.","Pesquisa criminológica e estatística criminal.","Inspeção e fiscalização dos estabelecimentos.","Representar pela interdição de estabelecimento."]'::jsonb, '["O Conselho Nacional REPRESENTA pela interdição; quem interdita é o juiz."]'::jsonb, 'O Conselho Nacional representa ao juiz para a interdição de um presídio inadequado.', '["Assertiva que permite ao Conselho Nacional interditar diretamente o estabelecimento erra: ele representa."]'::jsonb, '[]'::jsonb, '["Art. 66, VIII"]'::jsonb, 'under_review', 'claude'
