insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao Juiz da execução aplicar aos casos julgados lei posterior que favoreça o condenado; declarar extinta a punibilidade; decidir sobre soma ou unificação de penas, progressão ou regressão de regimes, detração e remição, suspensão condicional da pena, livramento condicional e incidentes da execução; autorizar saídas temporárias; determinar a forma de cumprimento da pena restritiva de direitos, as conversões de penas, a medida de segurança, a desinternação, o cumprimento em outra comarca e a remoção do condenado; decidir sobre a monitoração eletrônica; zelar pelo correto cumprimento da pena; inspecionar mensalmente os estabelecimentos penais; interditar, no todo ou em parte, estabelecimento em condições inadequadas; compor e instalar o Conselho da Comunidade; e emitir anualmente atestado de pena a cumprir.', '["Lei posterior mais benéfica.","Extinção da punibilidade.","Progressão, regressão, detração, remição, livramento condicional.","Saídas temporárias.","Inspeção mensal e interdição de estabelecimentos.","Atestado de pena a cumprir anual."]'::jsonb, '["O juiz inspeciona MENSALMENTE os estabelecimentos.","ATUALIZAÇÃO: o inciso X (atestado de pena a cumprir) foi incluído por lei posterior."]'::jsonb, 'O juiz da execução decide a progressão de regime e autoriza a saída temporária.', '["Assertiva que atribui ao diretor a decisão sobre progressão de regime erra: é do juiz da execução."]'::jsonb, '[]'::jsonb, '["Art. 65"]'::jsonb, 'under_review', 'claude'
