select u.id, u.content_sha256, 'O Conselho Penitenciário é órgão consultivo e fiscalizador da execução da pena. É integrado por membros nomeados pelo Governador do Estado, do Distrito Federal e dos Territórios, dentre professores e profissionais da área do Direito Penal, Processual Penal, Penitenciário e ciências correlatas, bem como por representantes da comunidade. O mandato dos membros tem a duração de 4 anos.', '["Órgão consultivo e fiscalizador.","Membros nomeados pelo Governador.","Mandato de 4 anos."]'::jsonb, '["Mandato de 4 anos (o do Conselho Nacional é de 2)."]'::jsonb, 'O Governador nomeia os membros do Conselho Penitenciário estadual.', '["Assertiva que fixa em 2 anos o mandato do Conselho Penitenciário erra: são 4 anos."]'::jsonb, '[]'::jsonb, '["Art. 70"]'::jsonb, 'under_review', 'claude'
