insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São atribuições do Departamento Penitenciário Nacional acompanhar a aplicação das normas de execução penal em todo o território; inspecionar e fiscalizar os estabelecimentos; assistir tecnicamente as Unidades Federativas; colaborar, por convênios, na implantação de estabelecimentos; colaborar na formação de pessoal penitenciário; estabelecer o cadastro nacional de vagas para cumprimento de pena aplicada por outra unidade federativa, especialmente para presos em regime disciplinar; e acompanhar a execução da pena das mulheres beneficiadas pela progressão especial do art. 112, §3º, monitorando sua integração social e a reincidência. Também coordena e supervisiona os estabelecimentos penais e de internamento federais.', '["Acompanhar a execução penal no país.","Inspeção e fiscalização.","Apoio técnico e convênios.","Cadastro nacional de vagas.","Acompanhamento da progressão especial das mulheres.","Supervisão dos estabelecimentos federais."]'::jsonb, '["ATUALIZAÇÃO: o inciso VII (progressão especial das mulheres) foi incluído por lei posterior."]'::jsonb, 'O Depen mantém o cadastro nacional de vagas prisionais.', '["Assertiva que atribui ao Depen apenas a gestão dos presídios estaduais erra: coordena os federais e apoia os estaduais."]'::jsonb, '[]'::jsonb, '["Art. 71"]'::jsonb, 'under_review', 'claude'
