select u.id, u.content_sha256, 'O Quadro do Pessoal Penitenciário será organizado em diferentes categorias funcionais, segundo as necessidades do serviço, com especificação de atribuições relativas às funções de direção, chefia e assessoramento do estabelecimento e às demais funções.', '["Quadro de pessoal em categorias funcionais."]'::jsonb, '["Organização conforme as necessidades do serviço."]'::jsonb, 'O quadro separa funções de direção, chefia e vigilância.', '["Assertiva que prevê categoria funcional única para o pessoal penitenciário erra."]'::jsonb, '[]'::jsonb, '["Art. 77"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-76'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A escolha do pessoal administrativo, especializado, de instrução técnica e de vigilância atenderá a vocação, preparação profissional e antecedentes pessoais do candidato. O ingresso, a progressão ou a ascensão funcional dependerão de cursos específicos de formação, procedendo-se à reciclagem periódica. No estabelecimento para mulheres somente se permitirá o trabalho de pessoal do sexo feminino, salvo quando se tratar de pessoal técnico especializado.', '["Seleção conforme vocação e antecedentes.","Cursos de formação e reciclagem.","Estabelecimento feminino: pessoal feminino, salvo técnico especializado."]'::jsonb, '["Pessoal FEMININO nos presídios femininos, salvo técnico especializado."]'::jsonb, 'A vigilância do presídio feminino é feita por agentes mulheres.', '["Assertiva que permite agentes de ambos os sexos na vigilância do presídio feminino erra, salvo o pessoal técnico especializado."]'::jsonb, '[]'::jsonb, '["Art. 76"]'::jsonb, 'under_review', 'claude'
