select u.id, u.content_sha256, 'O Patronato público ou particular destina-se a prestar assistência aos albergados e aos egressos.', '["Patronato presta assistência a albergados e egressos."]'::jsonb, '["Pode ser público ou particular."]'::jsonb, 'O Patronato apoia o egresso na busca por emprego.', '["Assertiva que restringe o Patronato aos presos do regime fechado erra: atende albergados e egressos."]'::jsonb, '[]'::jsonb, '["Art. 79"]'::jsonb, 'under_review', 'claude'
