insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Incumbe também ao Patronato orientar os condenados à pena restritiva de direitos; fiscalizar o cumprimento das penas de prestação de serviço à comunidade e de limitação de fim de semana; e colaborar na fiscalização do cumprimento das condições da suspensão e do livramento condicional.', '["Orientar condenados a penas restritivas.","Fiscalizar prestação de serviço e limitação de fim de semana.","Colaborar na fiscalização do sursis e do livramento condicional."]'::jsonb, '["Fiscaliza serviço à comunidade e limitação de fim de semana."]'::jsonb, 'O Patronato fiscaliza a frequência do condenado ao serviço comunitário.', '["Assertiva que isenta o Patronato da fiscalização do livramento condicional erra: ele colabora."]'::jsonb, '[]'::jsonb, '["Art. 78"]'::jsonb, 'under_review', 'claude'
