insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A guia de recolhimento, extraída pelo escrivão, que a rubricará em todas as folhas e a assinará com o juiz, será remetida à autoridade administrativa incumbida da execução e conterá o nome do condenado; sua qualificação civil e registro geral; o inteiro teor da denúncia e da sentença e a certidão de trânsito em julgado; a informação sobre antecedentes e grau de instrução; a data da terminação da pena; e outras peças reputadas indispensáveis. Ao Ministério Público se dará ciência. A guia será retificada sempre que sobrevier modificação quanto ao início da execução ou à duração da pena. Se o condenado era funcionário da Administração da Justiça Criminal, far-se-á menção.', '["Conteúdo da guia de recolhimento.","Ciência ao Ministério Público.","Retificação quando houver modificação.","Menção ao funcionário da Justiça Criminal."]'::jsonb, '["A guia é retificada sempre que mudar o início ou o tempo da pena."]'::jsonb, 'A guia informa a data de término da pena e traz a sentença.', '["Assertiva que dispensa a certidão de trânsito em julgado na guia erra."]'::jsonb, '[]'::jsonb, '["Art. 107"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-106'
