insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ninguém será recolhido, para cumprimento de pena privativa de liberdade, sem a guia expedida pela autoridade judiciária. A autoridade administrativa passará recibo da guia, para juntá-la aos autos, e dará ciência de seus termos ao condenado. As guias serão registradas em livro especial, em ordem cronológica, e anexadas ao prontuário, aditando-se o cálculo das remições e outras retificações.', '["Sem guia, ninguém é recolhido.","Recibo da guia e ciência ao condenado.","Registro em livro especial."]'::jsonb, '["Ninguém é recolhido SEM GUIA."]'::jsonb, 'A unidade só recebe o condenado com a guia judicial.', '["Assertiva que permite recolher o condenado antes da guia erra."]'::jsonb, '[]'::jsonb, '["Art. 106"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-107'
