insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado a quem sobrevier doença mental será internado em Hospital de Custódia e Tratamento Psiquiátrico.', '["Doença mental superveniente: internação no HCTP."]'::jsonb, '["Ver também o art. 183 (substituição por medida de segurança)."]'::jsonb, 'O condenado que adoece mentalmente é internado no HCTP.', '["Assertiva que mantém o condenado com doença mental superveniente no presídio comum erra."]'::jsonb, '[]'::jsonb, '["Art. 183"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-108'
