insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cumprida ou extinta a pena, o condenado será posto em liberdade, mediante alvará do Juiz, se por outro motivo não estiver preso.', '["Liberdade mediante alvará do juiz, se não estiver preso por outro motivo."]'::jsonb, '["Alvará de soltura do JUIZ."]'::jsonb, 'Cumprida a pena, o preso é solto com o alvará do juiz.', '["Assertiva que permite ao diretor soltar o preso sem alvará erra."]'::jsonb, '[]'::jsonb, '["Art. 110"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-109'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Juiz, na sentença, estabelecerá o regime no qual o condenado iniciará o cumprimento da pena privativa de liberdade, observado o art. 33 e seus parágrafos do Código Penal.', '["Regime inicial fixado na sentença."]'::jsonb, '["Observa o art. 33 do Código Penal."]'::jsonb, 'A sentença já define o regime inicial de cumprimento.', '["Assertiva que atribui ao diretor a fixação do regime inicial erra: é do juiz, na sentença."]'::jsonb, '[]'::jsonb, '["Código Penal, art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-110'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando houver condenação por mais de um crime, no mesmo processo ou em processos distintos, a determinação do regime de cumprimento será feita pelo resultado da soma ou unificação das penas, observada, quando for o caso, a detração ou remição. Sobrevindo condenação no curso da execução, somar-se-á a pena ao restante da que está sendo cumprida, para determinação do regime.', '["Regime pela soma ou unificação das penas.","Condenação superveniente soma-se ao restante."]'::jsonb, '["Regime definido pelo RESULTADO da soma."]'::jsonb, 'Duas condenações são somadas para definir o regime.', '["Assertiva que fixa o regime por cada pena isoladamente erra: pela soma ou unificação."]'::jsonb, '[]'::jsonb, '["Art. 112"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-111'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pena privativa de liberdade será executada de forma progressiva, com a transferência para regime menos rigoroso, quando o preso tiver cumprido ao menos 1/6 da pena no regime anterior e seu mérito indicar a progressão, com as seguintes exceções: primário em crime com violência ou grave ameaça, 25%; reincidente em crime com violência ou grave ameaça, 30%; reincidente em crime diverso, 20%; hediondo ou equiparado primário, 70%; 75% para hediondo com resultado morte (primário, vedado o livramento condicional), comando de organização criminosa ultraviolenta, constituição de milícia privada e feminicídio (primário); reincidente em hediondo ou equiparado, 80%; e reincidente em hediondo com resultado morte, 85%, vedado o livramento condicional. Exige-se boa conduta carcerária e, na decisão, manifestação do Ministério Público e do defensor. A mulher gestante ou mãe ou responsável por crianças ou pessoas com deficiência tem progressão especial, com 1/8 da pena, cumulando requisitos. O tráfico privilegiado não é hediondo. A falta grave interrompe o prazo da progressão, e o bom comportamento é readquirido após 1 ano.', '["Regra geral: 1/6 da pena.","Percentuais: 25%, 30%, 20%, 70%, 75%, 80% e 85%.","Boa conduta carcerária.","Progressão especial de 1/8 para mulheres gestantes e mães ou responsáveis.","Tráfico privilegiado não é hediondo.","Falta grave interrompe o prazo; bom comportamento é readquirido após 1 ano."]'::jsonb, '["ATUALIZAÇÃO: redação dada pelo Pacote Anticrime, com alterações posteriores (inclusive feminicídio e milícia privada).","A falta grave INTERROMPE o prazo da progressão.","Hediondo primário: 70%; reincidente em hediondo: 80%."]'::jsonb, 'O primário condenado por crime hediondo precisa cumprir 70% da pena para progredir.', '["Assertiva que fixa em 40% a fração do primário em crime hediondo erra: é 70% na redação vigente."]'::jsonb, '[{"termo":"Progressão de regime","significado":"Passagem para regime menos rigoroso após cumprir fração da pena."}]'::jsonb, '["Lei dos Crimes Hediondos"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-112'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O ingresso do condenado em regime aberto supõe a aceitação de seu programa e das condições impostas pelo Juiz.', '["Aceitação do programa e das condições judiciais."]'::jsonb, '["Aceitação do programa."]'::jsonb, 'O condenado aceita as condições antes de ir ao regime aberto.', '["Assertiva que dispensa a aceitação do programa pelo condenado erra."]'::jsonb, '[]'::jsonb, '["Art. 114"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-113'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Somente poderá ingressar no regime aberto o condenado que apresentar, pelos seus antecedentes e pelos resultados do exame criminológico, fundados indícios de que irá ajustar-se, com autodisciplina, baixa periculosidade e senso de responsabilidade, ao novo regime. Poderão ser dispensadas do trabalho as pessoas referidas no art. 117.', '["Indícios de ajuste ao regime aberto, com autodisciplina e baixa periculosidade.","Dispensa de trabalho para as pessoas do art. 117."]'::jsonb, '["ATUALIZAÇÃO: o inciso I (trabalho ou possibilidade imediata de trabalhar) foi revogado.","Hoje não se exige, por si, comprovação de trabalho."]'::jsonb, 'O condenado com baixa periculosidade e autodisciplina é admitido ao regime aberto.', '["Assertiva que ainda exige trabalho comprovado para o regime aberto como requisito legal expresso erra: o inciso I foi revogado."]'::jsonb, '[]'::jsonb, '["Art. 117"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-114'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz poderá estabelecer condições especiais para a concessão de regime aberto, entre as quais a fiscalização por monitoramento eletrônico, sem prejuízo das condições gerais e obrigatórias: permanecer no local designado durante o repouso e nos dias de folga; sair para o trabalho e retornar nos horários fixados; não se ausentar da cidade onde reside sem autorização judicial; e comparecer a Juízo, para informar e justificar suas atividades, quando determinado.', '["Condições especiais, inclusive monitoramento eletrônico.","Condições gerais obrigatórias: recolhimento, horários, não se ausentar da cidade e comparecer a Juízo."]'::jsonb, '["Quatro condições gerais e obrigatórias."]'::jsonb, 'O condenado no regime aberto não pode deixar a cidade sem autorização judicial.', '["Assertiva que dispensa a autorização judicial para sair da cidade no regime aberto erra."]'::jsonb, '[]'::jsonb, '["Art. 116"]'::jsonb, 'under_review', 'claude'
