insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Somente se admitirá o recolhimento do beneficiário de regime aberto em residência particular quando se tratar de condenado maior de 70 anos; condenado acometido de doença grave; condenada com filho menor ou deficiente físico ou mental; ou condenada gestante.', '["Maior de 70 anos.","Doença grave.","Condenada com filho menor ou com deficiência.","Condenada gestante."]'::jsonb, '["Prisão domiciliar da LEP: maior de 70 anos, doença grave, mãe de menor ou deficiente, gestante."]'::jsonb, 'O condenado de 72 anos no regime aberto pode cumprir em residência particular.', '["Assertiva que fixa em 60 anos a idade para a prisão domiciliar do art. 117 erra: são 70."]'::jsonb, '[]'::jsonb, '["Art. 114"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-117'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A execução da pena privativa de liberdade ficará sujeita à forma regressiva, com a transferência para qualquer dos regimes mais rigorosos, quando o condenado praticar fato definido como crime doloso ou falta grave; ou sofrer condenação, por crime anterior, cuja pena, somada ao restante da pena em execução, torne incabível o regime. O condenado será transferido do regime aberto se, além disso, frustrar os fins da execução ou não pagar, podendo, a multa cumulativamente imposta. Nas hipóteses de crime doloso ou falta grave e de frustração, deverá ser ouvido previamente o condenado.', '["Regressão por crime doloso ou falta grave.","Regressão por condenação que torne incabível o regime.","Do aberto: também por frustrar os fins da execução ou não pagar a multa podendo.","Oitiva prévia do condenado."]'::jsonb, '["Oitiva PRÉVIA do condenado.","Regressão pode ir a QUALQUER regime mais rigoroso."]'::jsonb, 'O condenado que comete falta grave é regredido, depois de ouvido.', '["Assertiva que dispensa a oitiva prévia do condenado na regressão erra."]'::jsonb, '[]'::jsonb, '["Art. 112"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-118'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A legislação local poderá estabelecer normas complementares para o cumprimento da pena privativa de liberdade em regime aberto, nos termos do art. 36, §1º, do Código Penal.', '["Normas complementares por legislação local."]'::jsonb, '["Competência complementar local."]'::jsonb, 'A lei estadual detalha regras do regime aberto.', '["Assertiva que veda qualquer regra local sobre o regime aberto erra."]'::jsonb, '[]'::jsonb, '["Art. 115"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-119'
