insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado por crimes contra a dignidade sexual somente ingressará em regime mais benéfico de cumprimento de pena ou perceberá benefício penal que autorize a saída do estabelecimento se os resultados do exame criminológico afirmarem a existência de indícios de que não voltará a cometer crimes da mesma natureza.', '["Exame criminológico obrigatório para crimes sexuais.","Indícios de que não reincidirá."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Exame criminológico OBRIGATÓRIO e favorável."]'::jsonb, 'A progressão do condenado por estupro depende de exame criminológico favorável.', '["Assertiva que dispensa o exame criminológico na progressão do condenado por crime sexual erra."]'::jsonb, '[]'::jsonb, '["Art. 112"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-119-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os condenados que cumprem pena em regime fechado ou semiaberto e os presos provisórios poderão obter permissão para sair do estabelecimento, mediante escolta, quando ocorrer falecimento ou doença grave do cônjuge, companheira, ascendente, descendente ou irmão, ou necessidade de tratamento médico. A permissão de saída será concedida pelo diretor do estabelecimento.', '["Permissão de saída com escolta.","Falecimento ou doença grave de familiar; tratamento médico.","Concedida pelo diretor."]'::jsonb, '["Permissão de saída: concedida pelo DIRETOR e com ESCOLTA.","Alcança regime fechado, semiaberto e presos provisórios."]'::jsonb, 'O preso sai com escolta para o velório da mãe, com autorização do diretor.', '["Assertiva que atribui ao juiz a concessão da permissão de saída erra: é do diretor do estabelecimento."]'::jsonb, '[]'::jsonb, '["Art. 122"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-120'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A permanência do preso fora do estabelecimento terá a duração necessária à finalidade da saída.', '["Duração necessária à finalidade."]'::jsonb, '["Tempo limitado à finalidade."]'::jsonb, 'A saída para o velório dura o tempo necessário.', '["Assertiva que fixa prazo mínimo de dias para a permissão de saída erra."]'::jsonb, '[]'::jsonb, '["Art. 120"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-121'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os condenados que cumprem pena em regime semiaberto poderão obter autorização para saída temporária do estabelecimento, sem vigilância direta, para frequência a curso supletivo profissionalizante, bem como de instrução do 2º grau ou superior, na Comarca do Juízo da Execução. A ausência de vigilância direta não impede o monitoramento eletrônico. Não terá direito à saída temporária ou a trabalho externo sem vigilância direta o condenado por crime hediondo ou com violência ou grave ameaça contra pessoa. Para estudo, o tempo de saída será o necessário às atividades discentes.', '["Saída temporária no regime semiaberto, sem vigilância direta.","Curso supletivo profissionalizante, ensino médio ou superior.","Vedada para condenado por crime hediondo ou com violência ou grave ameaça.","Monitoramento eletrônico possível."]'::jsonb, '["ATUALIZAÇÃO: os incisos I e III (visita à família e outras atividades) foram revogados; hoje a saída é para estudo.","Vedada a saída temporária ao condenado por crime hediondo ou com violência."]'::jsonb, 'O condenado em semiaberto sai para frequentar o curso superior.', '["Assertiva que permite a saída temporária ao condenado por crime hediondo erra."]'::jsonb, '[]'::jsonb, '["Art. 123"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-122'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autorização será concedida por ato motivado do Juiz da execução, ouvidos o Ministério Público e a administração penitenciária, e dependerá de comportamento adequado; cumprimento mínimo de 1/6 da pena, se o condenado for primário, e 1/4, se reincidente; e compatibilidade do benefício com os objetivos da pena.', '["Ato motivado do juiz, ouvidos MP e administração penitenciária.","Comportamento adequado.","Mínimo de 1/6 (primário) e 1/4 (reincidente).","Compatibilidade com a pena."]'::jsonb, '["1/6 se PRIMÁRIO; 1/4 se REINCIDENTE."]'::jsonb, 'O reincidente precisa de 1/4 da pena cumprida para a saída temporária.', '["Assertiva que fixa em 1/6 a fração do reincidente erra: é 1/4."]'::jsonb, '[]'::jsonb, '["Art. 122"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-123'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O benefício da saída temporária será automaticamente revogado quando o condenado praticar fato definido como crime doloso, for punido por falta grave, desatender as condições impostas ou revelar baixo grau de aproveitamento do curso. A recuperação do direito dependerá da absolvição no processo penal, do cancelamento da punição disciplinar ou da demonstração do merecimento.', '["Revogação automática por crime doloso, falta grave, descumprimento ou baixo aproveitamento.","Recuperação por absolvição, cancelamento da punição ou merecimento."]'::jsonb, '["Revogação AUTOMÁTICA."]'::jsonb, 'O condenado que comete falta grave perde a saída temporária.', '["Assertiva que exige decisão judicial prévia para a revogação automática erra."]'::jsonb, '[]'::jsonb, '["Art. 122"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-125'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado que cumpre a pena em regime fechado ou semiaberto poderá remir, por trabalho ou por estudo, parte do tempo de execução da pena. A contagem é feita à razão de 1 dia de pena a cada 12 horas de frequência escolar, divididas, no mínimo, em 3 dias, e de 1 dia de pena a cada 3 dias de trabalho. O estudo pode ser presencial ou a distância e deve ser certificado. As horas de trabalho e estudo são compatibilizadas para a cumulação. O preso impossibilitado por acidente continua a beneficiar-se. O tempo a remir pelo estudo é acrescido de 1/3 com a conclusão do ensino fundamental, médio ou superior. O condenado em regime aberto, semiaberto ou livramento condicional pode remir pela frequência a curso. O disposto aplica-se à prisão cautelar. A remição é declarada pelo juiz, ouvidos o MP e a defesa, e a prisão domiciliar não impede a remição.', '["Remição por trabalho (3 dias = 1 dia) e por estudo (12 horas = 1 dia).","Estudo presencial ou a distância, certificado.","Acréscimo de 1/3 com a conclusão do curso.","Aplica-se à prisão cautelar.","Declarada pelo juiz, ouvidos MP e defesa."]'::jsonb, '["Trabalho: 1 dia a cada 3 dias; estudo: 1 dia a cada 12 horas.","ATUALIZAÇÃO: remição por estudo e extensão à prisão cautelar vieram de leis posteriores."]'::jsonb, 'Trinta dias de trabalho geram dez dias de remição.', '["Assertiva que fixa um dia de remição para cada seis dias de trabalho erra: é um dia a cada três."]'::jsonb, '[{"termo":"Remição","significado":"Abatimento da pena por trabalho ou estudo."}]'::jsonb, '["Art. 127"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-126'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em caso de falta grave, o juiz poderá revogar até 1/3 do tempo remido, observado o disposto no art. 57, recomeçando a contagem a partir da data da infração disciplinar.', '["Revogação de até 1/3 do tempo remido.","Contagem recomeça da data da infração."]'::jsonb, '["ATUALIZAÇÃO: redação dada por lei posterior (antes era a perda total).","Até 1/3 do tempo remido."]'::jsonb, 'A falta grave pode fazer o preso perder até um terço dos dias remidos.', '["Assertiva que prevê a perda total do tempo remido na falta grave erra: é até 1/3."]'::jsonb, '[]'::jsonb, '["Art. 126"]'::jsonb, 'under_review', 'claude'
