insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade administrativa encaminhará mensalmente ao juízo da execução cópia do registro de todos os condenados que estejam trabalhando ou estudando, com informação dos dias de trabalho ou das horas de frequência escolar. O condenado autorizado a estudar fora do estabelecimento deverá comprovar mensalmente, por declaração da unidade de ensino, a frequência e o aproveitamento. Ao condenado dar-se-á a relação de seus dias remidos.', '["Relatório mensal ao juízo.","Comprovação mensal da frequência escolar externa.","Relação dos dias remidos ao condenado."]'::jsonb, '["Comunicação MENSAL ao juízo da execução."]'::jsonb, 'A unidade informa todo mês quantos dias cada preso trabalhou.', '["Assertiva que fixa envio trimestral do registro de trabalho erra: é mensal."]'::jsonb, '[]'::jsonb, '["Art. 126"]'::jsonb, 'under_review', 'claude'
