select u.id, u.content_sha256, 'O livramento condicional poderá ser concedido pelo Juiz da execução, presentes os requisitos do art. 83, incisos e parágrafo único, do Código Penal, ouvidos o Ministério Público e o Conselho Penitenciário.', '["Concedido pelo juiz da execução.","Ouvidos o MP e o Conselho Penitenciário."]'::jsonb, '["Oitiva do Conselho Penitenciário."]'::jsonb, 'O juiz concede o livramento depois de ouvir o MP e o Conselho Penitenciário.', '["Assertiva que atribui ao Conselho Penitenciário a concessão do livramento erra: é do juiz."]'::jsonb, '[]'::jsonb, '["Código Penal, art. 83"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-131'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deferido o pedido, o Juiz especificará as condições do livramento. Serão sempre impostas ao liberado condicional as obrigações de obter ocupação lícita, dentro de prazo razoável se for apto para o trabalho; comunicar periodicamente ao juiz sua ocupação; e não mudar do território da comarca sem prévia autorização. Poderão ainda ser impostas, entre outras, a obrigação de não mudar de residência sem comunicação, de recolher-se à habitação em hora fixada, de não frequentar determinados lugares e de utilizar equipamento de monitoração eletrônica.', '["Obrigações obrigatórias: ocupação lícita, comunicação e permanência na comarca.","Obrigações facultativas: residência, recolhimento, lugares e monitoração eletrônica."]'::jsonb, '["Três obrigações SEMPRE impostas."]'::jsonb, 'O liberado condicional não pode mudar de comarca sem autorização do juiz.', '["Assertiva que torna facultativa a obrigação de obter ocupação lícita erra: é sempre imposta."]'::jsonb, '[]'::jsonb, '["Art. 133"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-132'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

