select u.id, u.content_sha256, 'Se for permitido ao liberado residir fora da comarca do Juízo da execução, remeter-se-á cópia da sentença do livramento ao Juízo do lugar para onde ele se houver transferido e à autoridade incumbida da observação cautelar e de proteção.', '["Cópia da sentença ao juízo do novo local e à autoridade de observação."]'::jsonb, '["Comunicação ao novo local."]'::jsonb, 'O liberado muda de comarca com autorização, e o novo juízo recebe cópia da sentença.', '["Assertiva que dispensa a comunicação ao juízo do novo local erra."]'::jsonb, '[]'::jsonb, '["Art. 132"]'::jsonb, 'under_review', 'claude'
