insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A cerimônia do livramento condicional será realizada solenemente, no dia marcado pelo Presidente do Conselho Penitenciário, no estabelecimento onde se cumpre a pena. A sentença será lida ao liberando, na presença dos demais condenados, pelo Presidente do Conselho Penitenciário ou membro designado, ou, na falta, pelo juiz; a autoridade administrativa chamará a atenção para as condições; e o liberando declarará se as aceita. Lavra-se termo em livro próprio, e cópia é remetida ao juiz da execução.', '["Cerimônia solene no estabelecimento.","Leitura da sentença e advertência das condições.","Declaração de aceitação pelo liberando.","Termo em livro próprio, com cópia ao juiz."]'::jsonb, '["O liberando DECLARA se aceita as condições."]'::jsonb, 'Na cerimônia, o preso declara se aceita as condições do livramento.', '["Assertiva que dispensa a aceitação das condições pelo liberando erra."]'::jsonb, '[]'::jsonb, '["Art. 136"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-137'
