insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao sair o liberado do estabelecimento, ser-lhe-á entregue, além do saldo de seu pecúlio e do que lhe pertencer, uma caderneta, que exibirá à autoridade judiciária ou administrativa quando exigida. A caderneta conterá a identificação do liberado, o texto impresso do Capítulo e as condições impostas. Na falta, será entregue um salvo-conduto com as condições. Na caderneta e no salvo-conduto haverá espaço para consignar o cumprimento das condições.', '["Entrega do pecúlio e da caderneta.","Conteúdo da caderneta.","Salvo-conduto na falta da caderneta."]'::jsonb, '["Caderneta ou salvo-conduto."]'::jsonb, 'O liberado recebe a caderneta com as condições do livramento.', '["Assertiva que dispensa a entrega de documento ao liberado erra."]'::jsonb, '[]'::jsonb, '["Art. 132"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-138'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A observação cautelar e a proteção realizadas por serviço social penitenciário, Patronato ou Conselho da Comunidade terão a finalidade de fazer observar o cumprimento das condições especificadas na sentença e de proteger o beneficiário, orientando-o na execução de suas obrigações e auxiliando-o na obtenção de atividade laborativa. A entidade apresentará relatório ao Conselho Penitenciário, para efeito da representação prevista nos arts. 143 e 144.', '["Fiscalizar as condições.","Proteger e orientar o beneficiário.","Relatório ao Conselho Penitenciário."]'::jsonb, '["Fiscalização E proteção."]'::jsonb, 'O Patronato acompanha o liberado e auxilia na busca por emprego.', '["Assertiva que atribui à entidade apenas a fiscalização, sem proteção, erra."]'::jsonb, '[]'::jsonb, '["Art. 143"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-139'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A revogação do livramento condicional dar-se-á nas hipóteses previstas nos arts. 86 e 87 do Código Penal. Mantido o livramento, na hipótese de revogação facultativa, o juiz deverá advertir o liberado ou agravar as condições.', '["Revogação nas hipóteses dos arts. 86 e 87 do Código Penal.","Revogação facultativa: advertência ou agravamento das condições."]'::jsonb, '["Na revogação FACULTATIVA, o juiz pode apenas advertir ou agravar."]'::jsonb, 'Em caso de revogação facultativa, o juiz opta por advertir o liberado.', '["Assertiva que obriga o juiz a revogar sempre o livramento erra: na facultativa pode advertir ou agravar."]'::jsonb, '[]'::jsonb, '["Código Penal, arts. 86 e 87"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-140'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a revogação for motivada por infração penal anterior à vigência do livramento, computar-se-á como tempo de cumprimento da pena o período de prova, sendo permitida, para a concessão de novo livramento, a soma do tempo das 2 penas.', '["Infração anterior ao livramento: o período de prova conta como pena cumprida.","Soma das 2 penas para novo livramento."]'::jsonb, '["Período de prova computado como cumprimento de pena."]'::jsonb, 'Revogado o livramento por crime anterior, o tempo solto conta como pena cumprida.', '["Assertiva que não computa o período de prova na revogação por infração anterior erra."]'::jsonb, '[]'::jsonb, '["Art. 142"]'::jsonb, 'under_review', 'claude'
