select u.id, u.content_sha256, 'A revogação será decretada a requerimento do Ministério Público, mediante representação do Conselho Penitenciário, ou, de ofício, pelo Juiz, ouvido o liberado.', '["Requerimento do MP, representação do Conselho ou de ofício.","Oitiva do liberado."]'::jsonb, '["Oitiva do liberado."]'::jsonb, 'O juiz revoga o livramento depois de ouvir o liberado.', '["Assertiva que dispensa a oitiva do liberado na revogação erra."]'::jsonb, '[]'::jsonb, '["Art. 140"]'::jsonb, 'under_review', 'claude'
