insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Praticada pelo liberado outra infração penal, o Juiz poderá ordenar a sua prisão, ouvidos o Conselho Penitenciário e o Ministério Público, suspendendo o curso do livramento condicional, cuja revogação, entretanto, ficará dependendo da decisão final.', '["Prisão do liberado que comete nova infração.","Suspensão do livramento.","Revogação depende da decisão final."]'::jsonb, '["Suspensão do livramento, sem revogação imediata."]'::jsonb, 'O juiz prende o liberado que cometeu novo crime e suspende o livramento até a decisão final.', '["Assertiva que determina a revogação imediata do livramento com a nova infração erra: depende da decisão final."]'::jsonb, '[]'::jsonb, '["Art. 140"]'::jsonb, 'under_review', 'claude'
