insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz poderá definir a fiscalização por meio da monitoração eletrônica quando autorizar a saída temporária no regime semiaberto; determinar a prisão domiciliar; ou aplicar pena privativa de liberdade a ser cumprida nos regimes aberto ou semiaberto, ou conceder progressão para tais regimes.', '["Saída temporária no semiaberto.","Prisão domiciliar.","Regimes aberto ou semiaberto, inclusive na progressão."]'::jsonb, '["ATUALIZAÇÃO: incisos alterados e vetados em partes; confira a redação vigente."]'::jsonb, 'O juiz determina a tornozeleira para o condenado que progrediu ao regime aberto.', '["Assertiva que restringe a monitoração eletrônica ao regime fechado erra."]'::jsonb, '[{"termo":"Monitoração eletrônica","significado":"Fiscalização por tornozeleira ou dispositivo similar."}]'::jsonb, '["Art. 146-C"]'::jsonb, 'under_review', 'claude'
