insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Caberá ao Juiz da execução determinar a intimação do condenado, cientificando-o do local, dias e horário em que deverá cumprir a pena. A execução terá início a partir da data do primeiro comparecimento.', '["Intimação do condenado.","Início no primeiro comparecimento."]'::jsonb, '["Mesma regra de início do art. 149."]'::jsonb, 'O condenado é intimado do local e dos horários da limitação de fim de semana.', '["Assertiva que fixa o início da execução na data da sentença erra: é a do primeiro comparecimento."]'::jsonb, '[]'::jsonb, '["Art. 149"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-151'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Poderão ser ministrados ao condenado, durante o tempo de permanência, cursos e palestras, ou atribuídas atividades educativas. Nos casos de violência doméstica e familiar contra a criança, o adolescente e a mulher e de tratamento cruel ou degradante, ou de uso de formas violentas de educação, correção ou disciplina contra a criança e o adolescente, o juiz poderá determinar o comparecimento obrigatório do agressor a programas de recuperação e reeducação.', '["Cursos, palestras e atividades educativas.","Comparecimento obrigatório do agressor a programas de reeducação."]'::jsonb, '["ATUALIZAÇÃO: o parágrafo único foi ampliado por lei posterior (violência contra criança, adolescente e mulher)."]'::jsonb, 'O juiz determina que o agressor frequente programa de reeducação.', '["Assertiva que restringe o programa de reeducação aos casos de violência contra a mulher erra: abrange crianças e adolescentes."]'::jsonb, '[]'::jsonb, '["Lei Maria da Penha"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-152'
