select u.id, u.content_sha256, 'A pena privativa de liberdade, não superior a 2 anos, poderá ser convertida em restritiva de direitos, desde que o condenado a esteja cumprindo em regime aberto; tenha cumprido pelo menos 1/4 da pena; e os antecedentes e a personalidade indiquem ser a conversão recomendável.', '["Pena não superior a 2 anos.","Regime aberto.","Cumprimento de pelo menos 1/4.","Antecedentes e personalidade favoráveis."]'::jsonb, '["Pena até 2 anos, regime aberto e 1/4 cumprido."]'::jsonb, 'O condenado a 2 anos, em regime aberto, que cumpriu 1/4, pode ter a pena convertida.', '["Assertiva que dispensa o cumprimento de 1/4 da pena para a conversão erra."]'::jsonb, '[]'::jsonb, '["Art. 181"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-180'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pena restritiva de direitos será convertida em privativa de liberdade nas hipóteses e na forma do art. 45 e seus incisos do Código Penal. A prestação de serviços à comunidade será convertida quando o condenado não for encontrado ou desatender intimação por edital; não comparecer injustificadamente; recusar-se a prestar o serviço; praticar falta grave; ou sofrer condenação por outro crime à pena privativa de liberdade cuja execução não tenha sido suspensa. A limitação de fim de semana é convertida quando o condenado não comparecer ao estabelecimento, recusar-se à atividade, ou nas hipóteses de não localização, falta grave e nova condenação. A interdição temporária é convertida quando o condenado exercer, injustificadamente, o direito interditado, ou nas hipóteses de não localização e nova condenação.', '["Conversão da pena restritiva em privativa.","Hipóteses da prestação de serviços à comunidade.","Hipóteses da limitação de fim de semana.","Hipóteses da interdição temporária."]'::jsonb, '["Falta grave e nova condenação sem suspensão levam à conversão."]'::jsonb, 'Quem se recusa a prestar o serviço comunitário tem a pena convertida em privativa de liberdade.', '["Assertiva que impede a conversão da pena restritiva por falta grave erra."]'::jsonb, '[]'::jsonb, '["Art. 180"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-181'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
